TABLE_SQL = "\nCREATE TABLE @SCHEMA@.factor_native_publications (\n\tid UUID NOT NULL, \n\towner_id UUID NOT NULL, \n\trun_id UUID NOT NULL, \n\tattempt_id UUID NOT NULL, \n\tgeneration INTEGER NOT NULL, \n\tcutoff_id UUID NOT NULL, \n\tadmission_id UUID NOT NULL, \n\treservation_id UUID NOT NULL, \n\tsource_id UUID NOT NULL, \n\tsource_object_id UUID NOT NULL, \n\tsource_sha256 VARCHAR(64) NOT NULL, \n\tstop_receipt_id UUID NOT NULL, \n\textraction_receipt_id UUID NOT NULL, \n\tstop_kind VARCHAR(30) NOT NULL, \n\textraction_kind VARCHAR(30) NOT NULL, \n\tintent JSONB NOT NULL, \n\tintent_sha256 VARCHAR(64) NOT NULL, \n\tobject_id UUID NOT NULL, \n\tsha256 VARCHAR(64) NOT NULL, \n\tsize_bytes BIGINT NOT NULL, \n\tstorage_key VARCHAR(300) NOT NULL, \n\tjournal_key VARCHAR(300) NOT NULL, \n\tpeak_bytes BIGINT NOT NULL, \n\tpeak_entries INTEGER NOT NULL, \n\tcreated_at TIMESTAMP WITH TIME ZONE NOT NULL, \n\tPRIMARY KEY (id), \n\tUNIQUE (owner_id, run_id, attempt_id, generation, id), \n\tUNIQUE (owner_id, id, object_id, sha256, size_bytes, storage_key), \n\tUNIQUE (reservation_id), \n\tUNIQUE (admission_id), \n\tUNIQUE (object_id), \n\tFOREIGN KEY(owner_id, run_id, attempt_id, generation, admission_id) REFERENCES @SCHEMA@.research_process_admissions (owner_id, run_id, attempt_id, generation, id), \n\tFOREIGN KEY(owner_id, run_id, attempt_id, generation, reservation_id) REFERENCES @SCHEMA@.research_budget_reservations (owner_id, run_id, attempt_id, generation, id), \n\tFOREIGN KEY(owner_id, source_object_id, source_sha256) REFERENCES @SCHEMA@.factor_objects (owner_id, id, sha256), \n\tFOREIGN KEY(owner_id, run_id, attempt_id, generation, source_id) REFERENCES @SCHEMA@.factor_generation_sources (owner_id, run_id, attempt_id, generation, id), \n\tFOREIGN KEY(owner_id, run_id, attempt_id, generation, admission_id, stop_receipt_id, stop_kind) REFERENCES @SCHEMA@.research_process_receipts (owner_id, run_id, attempt_id, generation, admission_id, id, kind), \n\tFOREIGN KEY(owner_id, run_id, attempt_id, generation, admission_id, extraction_receipt_id, extraction_kind) REFERENCES @SCHEMA@.research_process_receipts (owner_id, run_id, attempt_id, generation, admission_id, id, kind), \n\tFOREIGN KEY(owner_id, run_id, attempt_id, generation, cutoff_id, admission_id, source_id) REFERENCES @SCHEMA@.factor_cutoff_executions (owner_id, run_id, attempt_id, generation, id, candidate_admission_id, evaluated_source_id), \n\tCHECK (stop_kind = 'stop' AND extraction_kind = 'extraction'), \n\tCHECK (generation > 0 AND size_bytes BETWEEN 1 AND 16777216), \n\tCHECK (sha256 ~ '^[a-f0-9]{64}$' AND intent_sha256 ~ '^[a-f0-9]{64}$'), \n\tCHECK (jsonb_typeof(intent) = 'object' AND octet_length(intent::text) <= 131072), \n\tCHECK (peak_bytes = 2 * size_bytes + 131072 AND peak_entries = 8), \n\tCHECK (storage_key = 'factors/' || owner_id::text || '/objects/' || sha256 || '.h5'), \n\tCHECK (journal_key = 'factors/' || owner_id::text || '/native-journals/' || id::text || '.json'), \n\tCHECK (stop_receipt_id <> extraction_receipt_id)\n)\n\n;\n\nCREATE TABLE @SCHEMA@.factor_native_objects (\n\tid UUID NOT NULL, \n\towner_id UUID NOT NULL, \n\tobject_kind VARCHAR(40) NOT NULL, \n\tsha256 VARCHAR(64) NOT NULL, \n\tsize_bytes BIGINT NOT NULL, \n\tstorage_key VARCHAR(300) NOT NULL, \n\tmedia_type VARCHAR(100) NOT NULL, \n\tcreated_at TIMESTAMP WITH TIME ZONE NOT NULL, \n\tPRIMARY KEY (id), \n\tUNIQUE (owner_id, id, sha256, size_bytes, storage_key), \n\tCHECK (object_kind = 'native_hdf' AND media_type = 'application/x-hdf5'), \n\tCHECK (size_bytes BETWEEN 1 AND 16777216 AND sha256 ~ '^[a-f0-9]{64}$'), \n\tCHECK (storage_key = 'factors/' || owner_id::text || '/objects/' || sha256 || '.h5')\n)\n\n;\n\nCREATE TABLE @SCHEMA@.factor_native_outcomes (\n\tpublication_id UUID NOT NULL, \n\towner_id UUID NOT NULL, \n\tobject_id UUID NOT NULL, \n\tsha256 VARCHAR(64) NOT NULL, \n\tsize_bytes BIGINT NOT NULL, \n\tstorage_key VARCHAR(300) NOT NULL, \n\tjournal_sha256 VARCHAR(64) NOT NULL, \n\tphysical_receipt_sha256 VARCHAR(64) NOT NULL, \n\tcreated_at TIMESTAMP WITH TIME ZONE NOT NULL, \n\tPRIMARY KEY (publication_id), \n\tFOREIGN KEY(owner_id, publication_id, object_id, sha256, size_bytes, storage_key) REFERENCES @SCHEMA@.factor_native_publications (owner_id, id, object_id, sha256, size_bytes, storage_key), \n\tFOREIGN KEY(owner_id, object_id, sha256, size_bytes, storage_key) REFERENCES @SCHEMA@.factor_native_objects (owner_id, id, sha256, size_bytes, storage_key), \n\tCHECK (journal_sha256 ~ '^[a-f0-9]{64}$' AND physical_receipt_sha256 ~ '^[a-f0-9]{64}$')\n)\n\n;\n\nCREATE TABLE @SCHEMA@.factor_native_normalizer_inputs (\n\tadmission_id UUID NOT NULL, \n\towner_id UUID NOT NULL, \n\trun_id UUID NOT NULL, \n\tattempt_id UUID NOT NULL, \n\tgeneration INTEGER NOT NULL, \n\tpublication_id UUID NOT NULL, \n\treservation_id UUID NOT NULL, \n\tobject_id UUID NOT NULL, \n\tsha256 VARCHAR(64) NOT NULL, \n\tsize_bytes BIGINT NOT NULL, \n\tstorage_key VARCHAR(300) NOT NULL, \n\tinput_sha256 VARCHAR(64) NOT NULL, \n\tintent_sha256 VARCHAR(64) NOT NULL, \n\tcreated_at TIMESTAMP WITH TIME ZONE NOT NULL, \n\tPRIMARY KEY (admission_id), \n\tUNIQUE (publication_id), \n\tUNIQUE (reservation_id), \n\tFOREIGN KEY(owner_id, run_id, attempt_id, generation, admission_id) REFERENCES @SCHEMA@.research_process_admissions (owner_id, run_id, attempt_id, generation, id), \n\tFOREIGN KEY(owner_id, run_id, attempt_id, generation, reservation_id) REFERENCES @SCHEMA@.research_budget_reservations (owner_id, run_id, attempt_id, generation, id), \n\tFOREIGN KEY(owner_id, run_id, attempt_id, generation, publication_id) REFERENCES @SCHEMA@.factor_native_publications (owner_id, run_id, attempt_id, generation, id), \n\tFOREIGN KEY(owner_id, publication_id, object_id, sha256, size_bytes, storage_key) REFERENCES @SCHEMA@.factor_native_publications (owner_id, id, object_id, sha256, size_bytes, storage_key), \n\tCHECK (generation > 0 AND input_sha256 ~ '^[a-f0-9]{64}$' AND intent_sha256 ~ '^[a-f0-9]{64}$')\n)\n\n;"

SEMANTIC_SQL = "\nCREATE FUNCTION @SCHEMA@.mineagent_native_check(pid uuid) RETURNS void LANGUAGE plpgsql SET search_path=pg_catalog AS $$\nDECLARE p @SCHEMA@.factor_native_publications%ROWTYPE;\n a @SCHEMA@.research_process_admissions%ROWTYPE; r @SCHEMA@.research_budget_reservations%ROWTYPE;\n st @SCHEMA@.research_process_receipts%ROWTYPE; ex @SCHEMA@.research_process_receipts%ROWTYPE;\n li @SCHEMA@.research_process_receipts%ROWTYPE; ident @SCHEMA@.research_process_receipts%ROWTYPE;\n c @SCHEMA@.factor_cutoff_executions%ROWTYPE;\n ev @SCHEMA@.factor_evaluation_starts%ROWTYPE; o @SCHEMA@.factor_native_outcomes%ROWTYPE;\n obj @SCHEMA@.factor_native_objects%ROWTYPE; j jsonb; output jsonb;\nBEGIN\n SELECT * INTO STRICT p FROM @SCHEMA@.factor_native_publications WHERE id=pid;\n SELECT * INTO STRICT a FROM @SCHEMA@.research_process_admissions WHERE id=p.admission_id;\n SELECT * INTO STRICT r FROM @SCHEMA@.research_budget_reservations WHERE id=p.reservation_id;\n SELECT * INTO STRICT st FROM @SCHEMA@.research_process_receipts WHERE id=p.stop_receipt_id;\n SELECT * INTO STRICT ex FROM @SCHEMA@.research_process_receipts WHERE id=p.extraction_receipt_id;\n SELECT * INTO STRICT li FROM @SCHEMA@.research_process_receipts WHERE admission_id=p.admission_id AND kind='launch_intent';\n SELECT * INTO STRICT ident FROM @SCHEMA@.research_process_receipts WHERE admission_id=p.admission_id AND kind='launch_identity';\n SELECT * INTO STRICT c FROM @SCHEMA@.factor_cutoff_executions WHERE id=p.cutoff_id;\n SELECT * INTO STRICT ev FROM @SCHEMA@.factor_evaluation_starts WHERE id=c.evaluation_id;\n j:=p.intent; output:=j->'output';\n IF (j - ARRAY['schema_version','journal_id','reservation_id','admission','source_id','generation_start_id','factor_version_id','source_object_id','source_sha256','prefix_sha256','snapshot_input_sha256','cutoff','stop_receipt_id','stop_receipt_sha256','extraction_receipt_id','extraction_receipt_sha256','output','journal_key']) <> '{}'::jsonb\n OR (j->>'schema_version',j->>'journal_id',j->>'reservation_id',j->>'source_id',j->>'source_object_id',j->>'source_sha256',j->>'stop_receipt_id',j->>'stop_receipt_sha256',j->>'extraction_receipt_id',j->>'extraction_receipt_sha256',j->>'journal_key') IS DISTINCT FROM\n ('mineagent.candidate-native-intent.v2',p.id::text,p.reservation_id::text,p.source_id::text,p.source_object_id::text,p.source_sha256,p.stop_receipt_id::text,st.payload_sha256,p.extraction_receipt_id::text,ex.payload_sha256,p.journal_key)\n OR j->'admission' IS DISTINCT FROM li.payload->'admission'\n OR (a.schema_version,a.role,a.ipc_policy,a.ticket_sha256) IS DISTINCT FROM\n ('mineagent.process-admission.v2'::varchar,'factor_cutoff_candidate'::varchar,'none'::varchar,NULL::varchar)\n OR a.logical_operation_id<>c.id OR a.reservation_id=p.reservation_id\n OR @SCHEMA@.mineagent_rd_source_violation(p.source_id) IS NOT NULL\n OR NOT EXISTS (SELECT 1 FROM @SCHEMA@.factor_source_read_witnesses w WHERE w.source_id=p.source_id\n   AND w.source_object_id=p.source_object_id AND w.source_sha256=p.source_sha256)\n OR (a.image_id,a.profile) IS DISTINCT FROM (c.projection->>'candidate_image',c.projection->>'candidate_profile')\n OR p.size_bytes>(c.projection->>'max_output_bytes')::bigint\n OR (c.cutoff_ordinal>=0 AND c.cutoff_ordinal<ev.expected_cutoffs) IS NOT TRUE\n OR ((c.projection->>'output_session')::date >= (ev.snapshot_input->'window'->>'start')::date\n     AND (c.projection->>'output_session')::date < (ev.snapshot_input->'window'->>'end')::date) IS NOT TRUE\n OR c.projection->>'snapshot_input_sha256' IS DISTINCT FROM ev.input_sha256\n OR NOT EXISTS (SELECT 1 FROM @SCHEMA@.factor_generation_starts gs JOIN @SCHEMA@.factor_research_specs rs ON rs.id=gs.spec_id\n   WHERE gs.id=c.start_id AND\n    (rs.config->'runtime'->>'candidate_image',rs.config->'runtime'->>'candidate_profile',rs.config->'runtime'->>'normalizer_image',rs.config->'runtime'->>'normalizer_profile') IS NOT DISTINCT FROM\n    (c.projection->>'candidate_image',c.projection->>'candidate_profile',c.projection->>'normalizer_image',c.projection->>'normalizer_profile'))\n\n OR c.projection_sha256<>encode(sha256(convert_to(@SCHEMA@.mineagent_native_metadata(c.projection),'UTF8')),'hex')\n OR ev.input_sha256<>encode(sha256(convert_to(@SCHEMA@.mineagent_native_metadata(ev.snapshot_input),'UTF8')),'hex')\n OR a.input_sha256<>encode(sha256(convert_to(@SCHEMA@.mineagent_native_metadata(li.payload->'inputs'),'UTF8')),'hex')\n OR (li.payload->'admission') IS DISTINCT FROM jsonb_build_object(\n   'schema_version',a.schema_version,'id',a.id,'owner_id',a.owner_id,'run_id',a.run_id,\n   'attempt_id',a.attempt_id,'generation',a.generation,'role',a.role,\n   'logical_operation_id',a.logical_operation_id,'launch_ordinal',a.launch_ordinal,\n   'profile',a.profile,'input_sha256',a.input_sha256,'reservation_id',a.reservation_id,\n   'image_id',a.image_id,'ipc',jsonb_build_object('ipc_policy','none','ticket_sha256',NULL))\n OR ident.payload->>'schema_version' IS DISTINCT FROM 'mineagent.numeric-process-identity.v2'\n OR ident.payload->>'admission_sha256' IS DISTINCT FROM encode(sha256(convert_to(@SCHEMA@.mineagent_native_metadata(li.payload->'admission'),'UTF8')),'hex')\n OR ident.payload->>'image_id' IS DISTINCT FROM a.image_id\n OR st.payload->>'schema_version' IS DISTINCT FROM 'mineagent.numeric-process-stop.v2'\n OR ex.payload->>'schema_version' IS DISTINCT FROM 'mineagent.numeric-process-extraction.v2'\n OR st.payload->'confirmed_absent' IS DISTINCT FROM 'true'::jsonb\n OR st.payload->'kernel_identity_absent' IS DISTINCT FROM 'true'::jsonb\n OR st.payload->'deadline_bound_met' IS DISTINCT FROM 'true'::jsonb\n OR ((st.payload->>'observed_at')::timestamptz >= (li.payload->>'issued_at')::timestamptz\n     AND (st.payload->>'observed_at')::timestamptz <= (li.payload->>'not_after')::timestamptz+interval '1 second') IS NOT TRUE\n\n OR ex.payload->'protected_frame_complete' IS DISTINCT FROM 'true'::jsonb\n OR ex.payload->'producer_quiesced' IS DISTINCT FROM 'true'::jsonb\n OR ex.payload->>'protocol' IS DISTINCT FROM 'MANU2'\n OR ex.payload->'size_bytes' IS DISTINCT FROM to_jsonb(p.size_bytes)\n OR ident.payload->>'container_id' IS NULL OR ident.payload->>'launch_sha256' IS NULL\n OR jsonb_typeof(ident.payload->'root_device') IS DISTINCT FROM 'number'\n OR jsonb_typeof(ident.payload->'root_inode') IS DISTINCT FROM 'number'\n OR (ident.payload->>'root_device') !~ '^[0-9]+$'\n OR (ident.payload->>'root_inode') !~ '^[1-9][0-9]*$'\n OR ident.payload->>'launch_sha256' IS DISTINCT FROM encode(sha256(convert_to(@SCHEMA@.mineagent_native_metadata(\n   jsonb_build_object('schema_version','mineagent.numeric-process-launch.v2','intent',li.payload,\n     'runtime_name','mineagent-numeric-'||a.id::text,\n     'root_device',ident.payload->'root_device','root_inode',ident.payload->'root_inode')),'UTF8')),'hex')\n\n OR (st.payload->>'container_id',st.payload->>'launch_sha256',st.payload->>'identity_sha256',ex.payload->>'launch_sha256',ex.payload->>'identity_sha256') IS DISTINCT FROM\n   (ident.payload->>'container_id',ident.payload->>'launch_sha256',ident.payload_sha256,ident.payload->>'launch_sha256',ident.payload_sha256)\n OR EXISTS (SELECT 1 FROM @SCHEMA@.research_process_receipts rc WHERE rc.admission_id=a.id AND\n   rc.payload_sha256<>encode(sha256(convert_to(@SCHEMA@.mineagent_native_metadata(rc.payload),'UTF8')),'hex'))\n\n OR NOT EXISTS (SELECT 1 FROM @SCHEMA@.research_process_states s WHERE s.admission_id=a.id AND s.status='stopped')\n OR (li.payload->'inputs'->>'source_object_id',li.payload->'inputs'->>'source_sha256',li.payload->'inputs'->>'prefix_sha256') IS DISTINCT FROM\n (p.source_object_id::text,p.source_sha256,c.projection_sha256)\n OR (j->>'generation_start_id',j->>'factor_version_id',j->>'prefix_sha256',j->>'snapshot_input_sha256') IS DISTINCT FROM\n (c.start_id::text,c.factor_version_id::text,c.projection_sha256,ev.input_sha256)\n OR (j->>'cutoff')::timestamptz IS DISTINCT FROM (c.projection->>'host_cutoff')::timestamptz\n OR (li.payload->'inputs'->>'cutoff')::timestamptz IS DISTINCT FROM (j->>'cutoff')::timestamptz\n OR (ex.kind,ex.payload->>'basename',ex.payload->>'sha256',(ex.payload->>'size_bytes')::bigint) IS DISTINCT FROM\n ('extraction'::varchar,'result.h5',p.sha256,p.size_bytes)\n OR st.kind<>'stop'\n OR octet_length(@SCHEMA@.mineagent_native_metadata(j))>65536\n OR encode(sha256(convert_to(@SCHEMA@.mineagent_native_metadata(j),'UTF8')),'hex')<>p.intent_sha256\n OR p.peak_bytes<>2*p.size_bytes+131072\n OR r.purpose<>'object_storage' OR r.amounts->>'storage_bytes' IS DISTINCT FROM p.peak_bytes::text\n OR EXISTS (SELECT 1 FROM jsonb_each(r.amounts) x WHERE x.key<>'storage_bytes' AND x.value<>'0'::jsonb)\n OR r.logical_key<>'native:'||p.id::text\n OR NOT EXISTS (SELECT 1 FROM @SCHEMA@.engine_object_reservation_consumers ec WHERE ec.reservation_id=p.reservation_id AND ec.consumer_kind='native_hdf' AND ec.consumer_id=p.id)\n THEN RAISE EXCEPTION 'Native publication binding differs'; END IF;\n IF output IS DISTINCT FROM jsonb_build_object('schema_version','mineagent.factor-storage-identity.v2',\n 'owner_id',p.owner_id,'storage_key',p.storage_key,'object',jsonb_build_object('role','native_hdf','object_id',p.object_id,\n 'object_kind','native_hdf','media_type','application/x-hdf5','sha256',p.sha256,'size_bytes',p.size_bytes))\n THEN RAISE EXCEPTION 'Native output identity differs'; END IF;\n SELECT * INTO o FROM @SCHEMA@.factor_native_outcomes WHERE publication_id=p.id;\n IF FOUND THEN\n  SELECT * INTO STRICT obj FROM @SCHEMA@.factor_native_objects WHERE id=p.object_id;\n  IF o.journal_sha256<>p.intent_sha256 OR o.physical_receipt_sha256<>\n    encode(sha256(convert_to(@SCHEMA@.mineagent_native_metadata(jsonb_build_object('storage_key',p.storage_key,'sha256',p.sha256,'size_bytes',p.size_bytes,'journal_key',p.journal_key,'journal_sha256',p.intent_sha256)),'UTF8')),'hex')\n   OR NOT EXISTS (SELECT 1 FROM @SCHEMA@.research_budget_settlements bs WHERE bs.reservation_id=r.id AND bs.outcome='conservative_unknown' AND bs.charge=r.amounts)\n   OR r.state<>'settled'\n  THEN RAISE EXCEPTION 'Native outcome/charge differs'; END IF;\n ELSE\n  IF r.state='settled' THEN RAISE EXCEPTION 'Pending native writer cannot be settled'; END IF;\n END IF;\n RETURN;\nEND $$;\n\nCREATE FUNCTION @SCHEMA@.mineagent_native_publication_consistent() RETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog AS $$\nDECLARE pid uuid;\nBEGIN\n IF TG_TABLE_NAME='factor_native_publications' THEN PERFORM @SCHEMA@.mineagent_native_check(NEW.id);\n ELSIF TG_TABLE_NAME='factor_native_outcomes' THEN PERFORM @SCHEMA@.mineagent_native_check(NEW.publication_id);\n ELSIF TG_TABLE_NAME='factor_native_objects' THEN\n  SELECT publication_id INTO pid FROM @SCHEMA@.factor_native_outcomes WHERE object_id=NEW.id;\n  IF NOT FOUND THEN RAISE EXCEPTION 'Native object requires publication outcome'; END IF;\n  PERFORM @SCHEMA@.mineagent_native_check(pid);\n ELSIF TG_TABLE_NAME IN ('research_budget_reservations','research_budget_settlements') THEN\n  FOR pid IN SELECT id FROM @SCHEMA@.factor_native_publications WHERE reservation_id=\n   (to_jsonb(NEW)->>CASE WHEN TG_TABLE_NAME='research_budget_reservations' THEN 'id' ELSE 'reservation_id' END)::uuid\n  LOOP PERFORM @SCHEMA@.mineagent_native_check(pid); END LOOP;\n ELSE RAISE EXCEPTION 'Unknown native evidence'; END IF;\n RETURN NEW;\nEND $$;\n\nCREATE FUNCTION @SCHEMA@.mineagent_native_run_guard() RETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog AS $$\nDECLARE rid uuid; aid uuid; moving boolean; ending boolean;\nBEGIN\n IF TG_TABLE_NAME='research_runs' THEN\n  rid:=NEW.id; aid:=NULL;\n  moving:=(NEW.generation,NEW.active_attempt_id) IS DISTINCT FROM (OLD.generation,OLD.active_attempt_id);\n  ending:=NEW.status IN ('succeeded','failed','cancelled') AND NEW.status IS DISTINCT FROM OLD.status;\n ELSE\n  rid:=NEW.run_id; aid:=NEW.id; moving:=false;\n  ending:=(NEW.finished_at IS NOT NULL AND OLD.finished_at IS NULL) OR (NEW.sandbox_stopped AND NOT OLD.sandbox_stopped);\n END IF;\n IF (moving OR ending) AND EXISTS (SELECT 1 FROM @SCHEMA@.factor_native_publications p\n   WHERE p.run_id=rid AND (aid IS NULL OR p.attempt_id=aid) AND NOT EXISTS\n   (SELECT 1 FROM @SCHEMA@.factor_native_outcomes o WHERE o.publication_id=p.id))\n THEN RAISE EXCEPTION 'Unresolved native publication prevents terminalization or resume'; END IF;\n RETURN NEW;\nEND $$;\n"

CLAIM_SQL = "\nALTER TABLE @SCHEMA@.engine_object_reservation_consumers DROP CONSTRAINT engine_object_reservation_consumers_consumer_kind_check;\nALTER TABLE @SCHEMA@.engine_object_reservation_consumers ADD CONSTRAINT engine_object_reservation_consumers_consumer_kind_check CHECK (consumer_kind IN ('research_object','factor_source','native_hdf'));\nCREATE OR REPLACE FUNCTION @SCHEMA@.mineagent_engine_object_claim() RETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog AS $$\nDECLARE kind text; rid uuid; previous @SCHEMA@.engine_object_reservation_consumers%ROWTYPE;\nBEGIN\n IF TG_TABLE_NAME='research_object_publications' THEN kind:='research_object'; rid:=NEW.budget_reservation_id;\n ELSIF TG_TABLE_NAME='factor_source_publications' THEN kind:='factor_source'; rid:=NEW.budget_reservation_id;\n ELSIF TG_TABLE_NAME='factor_native_publications' THEN kind:='native_hdf'; rid:=NEW.reservation_id;\n ELSE RAISE EXCEPTION 'Unknown reservation consumer'; END IF;\n -- The primary key arbitrates before bytes can be written, including concurrent\n -- snapshots. An invisible winner fails closed, never a second physical claim.\n PERFORM 1 FROM @SCHEMA@.research_budget_reservations WHERE id=rid FOR UPDATE;\n BEGIN\n  INSERT INTO @SCHEMA@.engine_object_reservation_consumers VALUES\n   (rid,NEW.owner_id,NEW.run_id,NEW.attempt_id,NEW.generation,kind,NEW.id);\n EXCEPTION WHEN unique_violation THEN\n  SELECT * INTO previous FROM @SCHEMA@.engine_object_reservation_consumers WHERE reservation_id=rid;\n  IF NOT FOUND OR (previous.owner_id,previous.run_id,previous.attempt_id,previous.generation,previous.consumer_kind,previous.consumer_id)\n   IS DISTINCT FROM (NEW.owner_id,NEW.run_id,NEW.attempt_id,NEW.generation,kind,NEW.id)\n  THEN RAISE EXCEPTION 'Reservation already belongs to another consumer'; END IF;\n END;\n RETURN NEW;\nEND $$;\nCREATE OR REPLACE FUNCTION @SCHEMA@.mineagent_engine_object_consistent() RETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog AS $$\nDECLARE rid uuid; claim @SCHEMA@.engine_object_reservation_consumers%ROWTYPE; n bigint; matching bigint;\nBEGIN\n IF TG_TABLE_NAME IN ('engine_object_reservation_consumers','factor_native_publications') THEN rid:=NEW.reservation_id;\n ELSIF TG_TABLE_NAME IN ('research_object_publications','factor_source_publications') THEN rid:=NEW.budget_reservation_id;\n ELSE RAISE EXCEPTION 'Unknown reservation consumer'; END IF;\n SELECT * INTO claim FROM @SCHEMA@.engine_object_reservation_consumers WHERE reservation_id=rid;\n IF NOT FOUND THEN RAISE EXCEPTION 'Reservation consumer claim missing'; END IF;\n SELECT count(*),count(*) FILTER (WHERE (kind,id,owner_id,run_id,attempt_id,generation)=\n  (claim.consumer_kind,claim.consumer_id,claim.owner_id,claim.run_id,claim.attempt_id,claim.generation)) INTO n,matching FROM (\n  SELECT 'research_object' AS kind,id,owner_id,run_id,attempt_id,generation FROM @SCHEMA@.research_object_publications WHERE budget_reservation_id=rid\n  UNION ALL SELECT 'factor_source',id,owner_id,run_id,attempt_id,generation FROM @SCHEMA@.factor_source_publications WHERE budget_reservation_id=rid\n  UNION ALL SELECT 'native_hdf',id,owner_id,run_id,attempt_id,generation FROM @SCHEMA@.factor_native_publications WHERE reservation_id=rid\n ) consumers;\n IF n<>1 OR matching<>1 THEN RAISE EXCEPTION 'Reservation requires exactly one matching physical consumer'; END IF;\n RETURN NEW;\nEND $$;\nCREATE TRIGGER claim_native_reservation BEFORE INSERT ON @SCHEMA@.factor_native_publications FOR EACH ROW EXECUTE FUNCTION @SCHEMA@.mineagent_engine_object_claim();\nCREATE CONSTRAINT TRIGGER check_native_consumer AFTER INSERT ON @SCHEMA@.factor_native_publications DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION @SCHEMA@.mineagent_engine_object_consistent();\n"

NORMALIZER_SQL = "\nCREATE FUNCTION @SCHEMA@.mineagent_native_normalizer_consistent() RETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog AS $$\nDECLARE p @SCHEMA@.factor_native_publications%ROWTYPE; a @SCHEMA@.research_process_admissions%ROWTYPE;\n li @SCHEMA@.research_process_receipts%ROWTYPE; r @SCHEMA@.research_budget_reservations%ROWTYPE;\n c @SCHEMA@.factor_cutoff_executions%ROWTYPE; listing jsonb; manifest jsonb; files jsonb;\nBEGIN\n SELECT * INTO STRICT p FROM @SCHEMA@.factor_native_publications WHERE id=NEW.publication_id;\n PERFORM @SCHEMA@.mineagent_native_check(p.id);\n IF NOT EXISTS(SELECT 1 FROM @SCHEMA@.factor_native_outcomes WHERE publication_id=p.id)\n THEN RAISE EXCEPTION 'Normalizer requires completed native publication'; END IF;\n SELECT * INTO STRICT a FROM @SCHEMA@.research_process_admissions WHERE id=NEW.admission_id;\n SELECT * INTO STRICT r FROM @SCHEMA@.research_budget_reservations WHERE id=NEW.reservation_id;\n SELECT * INTO STRICT li FROM @SCHEMA@.research_process_receipts WHERE admission_id=a.id AND kind='launch_intent';\n SELECT * INTO STRICT c FROM @SCHEMA@.factor_cutoff_executions WHERE id=p.cutoff_id;\n SELECT value INTO STRICT listing FROM jsonb_array_elements(c.projection->'input_files') WHERE value->>'name'='listings.json';\n manifest:=jsonb_build_object('schema_version','mineagent.factor-normalization.v1',\n  'hdf_sha256',p.sha256,'listings_sha256',listing->>'sha256',\n  'output_event_ns',(extract(epoch FROM (c.projection->>'output_event_time')::timestamptz)*1000000000)::bigint,\n  'max_rows',c.projection->'max_output_rows','max_bytes',c.projection->'max_output_bytes');\n files:=jsonb_build_array(\n  jsonb_build_object('destination','/input/listings.json','sha256',listing->>'sha256','size_bytes',listing->'size_bytes'),\n  jsonb_build_object('destination','/input/manifest.json','sha256',encode(sha256(convert_to(@SCHEMA@.mineagent_native_metadata(manifest),'UTF8')),'hex'),'size_bytes',octet_length(@SCHEMA@.mineagent_native_metadata(manifest))),\n  jsonb_build_object('destination','/input/result.h5','sha256',p.sha256,'size_bytes',p.size_bytes));\n IF (a.schema_version,a.role,a.ipc_policy,a.ticket_sha256,a.profile,a.image_id,a.logical_operation_id,a.reservation_id,a.input_sha256) IS DISTINCT FROM\n  ('mineagent.process-admission.v2'::varchar,'factor_normalizer'::varchar,'none'::varchar,NULL::varchar,\n   c.projection->>'normalizer_profile',c.projection->>'normalizer_image',c.id,NEW.reservation_id,NEW.input_sha256)\n OR li.payload_sha256<>NEW.intent_sha256\n OR encode(sha256(convert_to(@SCHEMA@.mineagent_native_metadata(li.payload),'UTF8')),'hex')<>NEW.intent_sha256\n OR encode(sha256(convert_to(@SCHEMA@.mineagent_native_metadata(li.payload->'inputs'),'UTF8')),'hex')<>a.input_sha256\n OR (li.payload->'admission') IS DISTINCT FROM jsonb_build_object(\n   'schema_version',a.schema_version,'id',a.id,'owner_id',a.owner_id,'run_id',a.run_id,\n   'attempt_id',a.attempt_id,'generation',a.generation,'role',a.role,\n   'logical_operation_id',a.logical_operation_id,'launch_ordinal',a.launch_ordinal,\n   'profile',a.profile,'input_sha256',a.input_sha256,'reservation_id',a.reservation_id,\n   'image_id',a.image_id,'ipc',jsonb_build_object('ipc_policy','none','ticket_sha256',NULL))\n OR (li.payload->'inputs'->>'source_object_id',li.payload->'inputs'->>'source_sha256',li.payload->'inputs'->>'prefix_sha256') IS DISTINCT FROM\n   (p.source_object_id::text,p.source_sha256,c.projection_sha256)\n OR (li.payload->'inputs'->>'cutoff')::timestamptz IS DISTINCT FROM (c.projection->>'host_cutoff')::timestamptz\n OR li.payload->'inputs'->'files' IS DISTINCT FROM files\n OR r.purpose<>'process_unit' OR (r.amounts->>'process_slots')::numeric<1\n OR (r.amounts->>'wall_milliseconds')::numeric<60000 OR (r.amounts->>'storage_bytes')::numeric<67174400\n THEN RAISE EXCEPTION 'Native normalizer admission/input/reservation differs'; END IF;\n RETURN NEW;\nEND $$;\nCREATE TRIGGER protect_factor_native_normalizer_inputs BEFORE UPDATE OR DELETE ON @SCHEMA@.factor_native_normalizer_inputs FOR EACH ROW EXECUTE FUNCTION @SCHEMA@.mineagent_protect_neutral();\nCREATE CONSTRAINT TRIGGER check_native_normalizer AFTER INSERT OR UPDATE ON @SCHEMA@.factor_native_normalizer_inputs DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION @SCHEMA@.mineagent_native_normalizer_consistent();\n"

CANONICAL_SQL = "\nCREATE FUNCTION @SCHEMA@.mineagent_native_metadata(v jsonb, depth integer DEFAULT 0)\nRETURNS text LANGUAGE plpgsql IMMUTABLE STRICT SET search_path=pg_catalog AS $$\nBEGIN\n IF depth<0 OR depth>16 OR octet_length(v::text)>1048576 THEN\n  RAISE EXCEPTION 'Native metadata exceeds fixed bound'; END IF;\n RETURN @SCHEMA@.mineagent_rd_canonical_json(v,true,depth);\nEND $$;\n"

PRIOR_CLAIM_SQL = "CREATE OR REPLACE FUNCTION @SCHEMA@.mineagent_engine_object_claim() RETURNS trigger LANGUAGE plpgsql SET search_path=@SCHEMA@,pg_catalog AS $$\nDECLARE kind text; previous @SCHEMA@.engine_object_reservation_consumers%ROWTYPE;\nBEGIN\n IF TG_TABLE_NAME = 'research_object_publications' THEN kind := 'research_object';\n ELSIF TG_TABLE_NAME = 'factor_source_publications' THEN kind := 'factor_source';\n ELSE RAISE EXCEPTION 'Unknown reservation consumer'; END IF;\n BEGIN\n  INSERT INTO @SCHEMA@.engine_object_reservation_consumers\n  VALUES (NEW.budget_reservation_id, NEW.owner_id, NEW.run_id, NEW.attempt_id, NEW.generation, kind, NEW.id);\n EXCEPTION WHEN unique_violation THEN\n  SELECT * INTO previous FROM @SCHEMA@.engine_object_reservation_consumers WHERE reservation_id = NEW.budget_reservation_id;\n  IF NOT FOUND OR (previous.owner_id, previous.run_id, previous.attempt_id, previous.generation, previous.consumer_kind, previous.consumer_id)\n    IS DISTINCT FROM (NEW.owner_id, NEW.run_id, NEW.attempt_id, NEW.generation, kind, NEW.id) THEN\n   RAISE EXCEPTION 'Reservation already belongs to another consumer';\n  END IF;\n END;\n RETURN NEW;\nEND $$;\nCREATE OR REPLACE FUNCTION @SCHEMA@.mineagent_engine_object_consistent() RETURNS trigger LANGUAGE plpgsql SET search_path=@SCHEMA@,pg_catalog AS $$\nDECLARE rid uuid; claim @SCHEMA@.engine_object_reservation_consumers%ROWTYPE;\n        actual_count bigint; matching_count bigint;\nBEGIN\n IF TG_TABLE_NAME = 'engine_object_reservation_consumers' THEN rid := NEW.reservation_id;\n ELSIF TG_TABLE_NAME IN ('research_object_publications','factor_source_publications') THEN rid := NEW.budget_reservation_id;\n ELSE RAISE EXCEPTION 'Unknown reservation consumer'; END IF;\n SELECT * INTO claim FROM @SCHEMA@.engine_object_reservation_consumers WHERE reservation_id = rid;\n IF NOT FOUND THEN RAISE EXCEPTION 'Reservation consumer claim missing'; END IF;\n SELECT count(*), count(*) FILTER (WHERE kind = claim.consumer_kind AND id = claim.consumer_id AND owner_id = claim.owner_id AND run_id = claim.run_id AND attempt_id = claim.attempt_id AND generation = claim.generation)\n INTO actual_count, matching_count FROM (\n  SELECT 'research_object' AS kind, id, owner_id, run_id, attempt_id, generation FROM @SCHEMA@.research_object_publications WHERE budget_reservation_id = rid\n  UNION ALL\n  SELECT 'factor_source' AS kind, id, owner_id, run_id, attempt_id, generation FROM @SCHEMA@.factor_source_publications WHERE budget_reservation_id = rid\n ) consumers;\n IF actual_count <> 1 OR matching_count <> 1 THEN\n  RAISE EXCEPTION 'Reservation requires exactly one matching physical consumer';\n END IF;\n RETURN NEW;\nEND $$;"

TABLES = (
    "factor_native_publications",
    "factor_native_objects",
    "factor_native_outcomes",
)
ALL_TABLES = TABLES + ("factor_native_normalizer_inputs",)


def _schema():
    value = op.get_bind().exec_driver_sql("SELECT current_schema()").scalar_one()
    if type(value) is not str or re.fullmatch(r"[a-z][a-z0-9_]{0,62}", value) is None:
        raise RuntimeError("Exact installation schema required")
    return '"' + value + '"'


def maintenance(schema):
    op.execute("""DO $$ BEGIN
      IF current_setting('transaction_isolation') <> 'read committed'
      THEN RAISE EXCEPTION 'Native storage migration requires READ COMMITTED'; END IF;
      IF NOT pg_try_advisory_xact_lock(1413960260, 1129270340)
      THEN RAISE EXCEPTION 'Native storage migration requires quiescent maintenance'; END IF;
    END $$;""")
    tables = (
        "research_runs",
        "execution_attempts",
        "research_process_admissions",
        "research_process_receipts",
        "research_object_publications",
        "factor_source_publications",
        "engine_object_reservation_consumers",
        "research_budget_reservations",
        "research_budget_settlements",
        "factor_cutoff_executions",
        "factor_generation_sources",
        "factor_objects",
    )
    op.execute(
        "LOCK TABLE "
        + ",".join(schema + "." + table for table in tables)
        + " IN ACCESS EXCLUSIVE MODE NOWAIT"
    )
    op.execute("SET LOCAL search_path = " + schema + ", pg_catalog")


def upgrade():
    schema = _schema()
    maintenance(schema)
    for sql in (TABLE_SQL, CLAIM_SQL, CANONICAL_SQL, SEMANTIC_SQL, NORMALIZER_SQL):
        op.execute(sql.replace("@SCHEMA@", schema))
    for table in TABLES:
        op.execute(
            f"CREATE TRIGGER protect_{table} BEFORE UPDATE OR DELETE ON {schema}.{table} FOR EACH ROW EXECUTE FUNCTION {schema}.mineagent_protect_neutral()"
        )
        op.execute(
            f"CREATE CONSTRAINT TRIGGER check_{table}_native AFTER INSERT OR UPDATE ON {schema}.{table} DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION {schema}.mineagent_native_publication_consistent()"
        )
    for table in ("research_budget_reservations", "research_budget_settlements"):
        op.execute(
            f"CREATE CONSTRAINT TRIGGER check_{table}_native AFTER INSERT OR UPDATE ON {schema}.{table} DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION {schema}.mineagent_native_publication_consistent()"
        )
    for table in ("research_runs", "execution_attempts"):
        op.execute(
            f"CREATE TRIGGER guard_native_terminal BEFORE UPDATE ON {schema}.{table} FOR EACH ROW EXECUTE FUNCTION {schema}.mineagent_native_run_guard()"
        )


def downgrade():
    schema = _schema()
    maintenance(schema)
    op.execute(
        "LOCK TABLE "
        + ",".join(schema + "." + table for table in ALL_TABLES)
        + " IN ACCESS EXCLUSIVE MODE NOWAIT"
    )
    checks = " OR ".join(
        f"EXISTS(SELECT 1 FROM {schema}.{table})" for table in ALL_TABLES
    )
    checks += f" OR EXISTS(SELECT 1 FROM {schema}.engine_object_reservation_consumers WHERE consumer_kind='native_hdf')"
    op.execute(
        "DO $$ BEGIN IF "
        + checks
        + " THEN RAISE EXCEPTION 'Native evidence prevents downgrade'; END IF; END $$;"
    )
    # No CASCADE: unexpected dependencies must fail, never erase evidence.
    for table in ("research_budget_reservations", "research_budget_settlements"):
        op.execute(f"DROP TRIGGER check_{table}_native ON {schema}.{table}")
    for table in ("research_runs", "execution_attempts"):
        op.execute(f"DROP TRIGGER guard_native_terminal ON {schema}.{table}")
    for table in (
        "factor_native_normalizer_inputs",
        "factor_native_outcomes",
        "factor_native_objects",
        "factor_native_publications",
    ):
        op.execute(f"DROP TABLE {schema}.{table}")
    for signature in (
        "mineagent_native_normalizer_consistent()",
        "mineagent_native_publication_consistent()",
        "mineagent_native_run_guard()",
        "mineagent_native_check(uuid)",
        "mineagent_native_metadata(jsonb,integer)",
    ):
        op.execute(f"DROP FUNCTION {schema}.{signature}")
    op.execute(PRIOR_CLAIM_SQL.replace("@SCHEMA@", schema))
    op.execute(
        f"ALTER TABLE {schema}.engine_object_reservation_consumers DROP CONSTRAINT engine_object_reservation_consumers_consumer_kind_check"
    )
    op.execute(
        f"ALTER TABLE {schema}.engine_object_reservation_consumers ADD CONSTRAINT engine_object_reservation_consumers_consumer_kind_check CHECK (consumer_kind IN ('research_object','factor_source'))"
    )
